     IF meta->>'source'='clan' AND meta->>'id'='214af896-15f8-43e6-858b-614d2851dd3b' AND clan_akimichi_private.replacement_applies(a.id) THEN
       meta:=clan_akimichi_private.partial_meta(a.id,meta);
