export function editorialPrompt(role) {
  if (!Object.hasOwn(roles, role)) throw new Error('editorial_role_unknown');
  const applicable = role === 'help_audit' ? [rules[0], rules[1], rules[2], rules[5]] : rules;
  return [EDITORIAL_VERSION, ...applicable, roles[role]].join('\n\n');
}

// Stesso runtime, prompt, limiti e provider; solo porte di persistenza dedicate.
import {sceneOrdinary} from './runtime.ts';
const methods=new Map(['acquire','permit','status','save','complete'].map(x=>[
  `combat_consumer_scene_${x}_${x==='permit'?'v3':'v2'}`,
  `combat_consumer_recovery_${x}_${x==='permit'?'v2':'v1'}`
]));
export async function recoveryOrdinary(body:any,channel:any,dependencies:any){
  if(!body || body.recovery!==true || Object.keys(body).some(k=>!['recovery','ordinary_round_id','report_sha256','request_key'].includes(k)))
    return {status:400,data:{error:'recovery_request_invalid'}};
  const {recovery,...request}=body;
  const adapter={rpc:(name:string,params:any,signal:AbortSignal)=>{
    if(['combat_consumer_count_start_v1','combat_consumer_count_finish_v1'].includes(name))
      return channel.rpc(name,{...params,p_recovery:true},signal);
    const method=methods.get(name);
    if(!method)throw new Error('recovery_rpc_not_allowed');
    return channel.rpc(method,params,signal);
  }};
  return sceneOrdinary(request,adapter,dependencies);
}

import { runSceneNarrative } from './lifecycle.mjs';
import { canonical } from './scene.mjs';
import {validateS22Profile,validateS22Measurement,validateCountStart,validCountResponse,validateCountFinish} from './count.mjs';
import { EDGE_REVISION, VALIDATOR_REVISION } from './editorial.mjs';

const caps: Record<string, number> = {claim: 10000, status: 3000, reserve: 4000, provider: 45000,
  persist: 6000, publish: 6000, audit: 1000};
const reserves: Record<string, number> = {claim: 18000, status: 0, reserve: 14000, provider: 13000,
  persist: 6000, publish: 3000, audit: 6000};
export class SceneBudget {
  deadline: number;
  leaseDeadline = Infinity;
  financial = false;
  financialExpiresAt = Infinity;
  constructor(remainingMs = 50000) { this.deadline = performance.now() + remainingMs; }
  async run(phase: string, fn: (signal: AbortSignal) => Promise<any>) {
    const started = performance.now();
    const finiteCaps: Record<string,number> = {count_start:2000,count:8000,count_finish:3000,persist:4000,publish:3000,audit:1000};
    const finiteReserves: Record<string,number> = {count_start:23000,count:15000,count_finish:12000,reserve:8000,provider:8000,persist:4000,publish:1000,audit:0};
    const reserve = this.financial ? (finiteReserves[phase] ?? reserves[phase] ?? 0) : (reserves[phase] ?? 0);
    const cap = this.financial ? (finiteCaps[phase] ?? caps[phase] ?? 0) : (caps[phase] ?? 0);
    const leaseBound = ['reserve', 'provider', 'persist', 'count_start', 'count', 'count_finish'].includes(phase) ? this.leaseDeadline : Infinity;
    const ms = Math.min(cap, this.deadline - started - reserve, leaseBound - started - reserve);
    if (!Number.isFinite(ms) || ms <= 0) throw new Error('scene_budget_exhausted');
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const timeout = new Promise<never>((_, reject) => { timer = setTimeout(() => {controller.abort(); reject(new Error('scene_phase_timeout'));}, ms); });
    try {
      const result = await Promise.race([Promise.resolve().then(() => fn(controller.signal)), timeout]);
      if(this.financial && typeof result?.server_now==='string') {
        const ttl=this.financialExpiresAt-Date.parse(result.server_now);
        if(!Number.isFinite(ttl))throw new Error('scene_financial_deadline_invalid');
        this.deadline=Math.min(this.deadline,started+ttl);
      }
      if (typeof result?.server_now === 'string' && typeof result?.expires_at === 'string') {
        const ttl = Date.parse(result.expires_at) - Date.parse(result.server_now);
        if (!Number.isFinite(ttl)) throw new Error('scene_lease_invalid');
        // L'intero RTT è sottratto: nessuna assunzione di orologi client/server sincronizzati.
        this.leaseDeadline = started + ttl;
      }
      return result;
    } finally { if (timer !== undefined) clearTimeout(timer); }
  }
}

export async function sceneOrdinary(body: any, channel: any, options: any) {
  const request = {round_id: body?.ordinary_round_id, report_sha256: body?.report_sha256, request_key: body?.request_key};
  const uuid = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
  if (!body || Object.keys(body).length !== 3 || !uuid.test(request.round_id) || !uuid.test(request.request_key))
    return {status: 400, data: {error: 'scene_request_invalid'}};
  const budget = new SceneBudget(50000 - (Date.now() - options.startedAt));
  const params = {p_round: request.round_id, p_report_sha256: request.report_sha256, p_request_key: request.request_key};
  const rpc = async (name: string, extra: any, signal: AbortSignal) => {
    const r = await channel.rpc(name, {...params, ...extra}, signal);
    if (r.error || !r.data) throw new Error('scene_rpc_uncertain');
    return r.data;
  };
  const limits = {transportMaxChars: 5000, maxInputBytes: 49152, maxRequestBytes: 65536, maxOutputTokens: 9992};
  let financialProfile: any = null;
  let countBinding: any = null;
  const checkedRecord = (r: any) => {
    if (!r.limits || Object.keys(r.limits).length !== Object.keys(limits).length
      || Object.entries(limits).some(([k,v]) => r.limits[k] !== v)
      || r.scene?.snapshot?.selection?.max_input_bytes !== limits.maxInputBytes)
      throw new Error('scene_contract_incompatible');
    if (Object.hasOwn(r,'staff_financial_profile')) {
      financialProfile=validateS22Profile(r.staff_financial_profile,r.binding?.session_id);
      if(typeof r.server_now!=='string'||!Number.isFinite(Date.parse(r.server_now)))throw new Error('scene_contract_incompatible');
      budget.financial=true;budget.financialExpiresAt=Date.parse(financialProfile.deadline);
    } else if (financialProfile!==null || ['7a26b454-b4e1-4471-be0c-8a1520b5b9e0','0e5b5163-b42d-4c07-b2cd-7278a0d79340'].includes(r.binding?.session_id)) throw new Error('scene_contract_incompatible');
    return r;
  };
  // A qualified S24 financial profile narrows only the provider request cap;
  // the native record/scene codec keeps its existing 9992 upper unchanged.
  const generationLimits = () => financialProfile?.session_id==='0e5b5163-b42d-4c07-b2cd-7278a0d79340'
    ? {...limits,maxOutputTokens:financialProfile.max_output_tokens} : limits;
  let aiUsage: any;
  const result = await runSceneNarrative(request, {
    limits, phase: (p: string, fn: any) => budget.run(p, fn),
    acquire: async (_: any, signal: AbortSignal) => {
      return checkedRecord(await rpc('combat_consumer_scene_acquire_v2', {}, signal));
    },
    status: async (_: any, signal: AbortSignal) => checkedRecord(await rpc('combat_consumer_scene_status_v2', {}, signal)),
    reserve: async (_: any, b: any, signal: AbortSignal) => {
      const permission = await rpc('combat_consumer_scene_permit_v3',
        {p_scene_sha256: b.snapshot_sha256, p_control_version: b.control_version}, signal);
      // Il bit arriva dal DB; assente/sconosciuto non può autorizzare HTTP.
      if (typeof permission.quota_required !== 'boolean') throw new Error('scene_quota_contract_incompatible');
      if (financialProfile && (!countBinding || permission.generation_request_sha256!==countBinding.generation_request_sha256))
        throw new Error('scene_count_permission_binding');
      return permission;
    },
    persist: (_: any, p: any, _hash: string, signal: AbortSignal) => rpc('combat_consumer_scene_save_v2', {p_result_text: canonical(p)}, signal),
    publish: (_: any, signal: AbortSignal) => rpc('combat_consumer_scene_complete_v2', {}, signal),
    checkProviderBudget: async (p: any) => {
      const measurement=await options.measure(p,generationLimits());
      if (!financialProfile) return;
      validateS22Measurement(measurement);
      const start=await budget.run('count_start',signal=>rpc('combat_consumer_count_start_v1',{
        p_recovery:false,p_payload_text:measurement.payload_text,p_payload_sha:measurement.generation_request_sha256},signal));
      const reused=validateCountStart(start,measurement.generation_request_sha256);
      if (!reused) {
        let status='unknown',response:any={};
        try { const measured=await budget.run('count',signal=>options.count(measurement.count_payload,signal));
          if (!validCountResponse(measured)) throw new Error('scene_count_response_invalid');
          status='success';response=measured;
        } catch { /* The original sent ticket remains accounted. No second Count HTTP. */ }
        const proof=await budget.run('count_finish',signal=>rpc('combat_consumer_count_finish_v1',{
          p_recovery:false,p_count_ticket:start.count_ticket,p_status:status,p_response:response},signal));
        validateCountFinish(proof,start,measurement.generation_request_sha256,status);
      }
      countBinding=Object.freeze({generation_request_sha256:measurement.generation_request_sha256,payload_text:measurement.payload_text,count_ticket:start.count_ticket});
    },
    generate: async (p: any, signal: AbortSignal, onAttempt: any, permission: any) => {
      let transportStarted = false;
      const ai = await options.generate(p, signal, () => { onAttempt(); transportStarted = true; }, generationLimits(), permission, countBinding);
      // L'adattatore conta il tentativo prima del fetchImpl; il wrapper può
      // negarlo prima del POST. Il contatore autorevole è questa callback.
      aiUsage = {...ai, tentativi_http: transportStarted ? 1 : 0};
      return {provider: ai.provider, model: ai.model, http_attempts: aiUsage.tentativi_http, response_id: ai.provider_response_id,
        request_sha256: ai.provider_request_sha256, raw_sha256: ai.raw_output_sha256,
        input_tokens: ai.input_tokens, output_tokens: ai.output_tokens, text: ai.text,
        complete: ai.ok === true && ai.stop_reason === 'end_turn' && ai.troncato !== true};
    },
    mechanicalCodes: (raw: string, snapshot: any) => options.mechanicalCodes(raw, JSON.parse(snapshot.resolved_facts)),
    audit: (delivery: any, diagnostics: any, signal: AbortSignal) => options.audit(aiUsage, delivery, diagnostics, signal),
  });
  return {status: result.state === 'published' || result.state === 'failed' ? 200 : 503,
    data: {...result,...(financialProfile?{provider_retry_allowed:false}:{}), edge_revision: EDGE_REVISION, validator_revision: VALIDATOR_REVISION}};
}

import {scenePrompts, inspectNarrative, EDGE_REVISION, VALIDATOR_REVISION} from './editorial.mjs';
import {canonical, digest} from './scene.mjs';

export const LIFECYCLE_VERSION = 'combat-narrative-lifecycle/1';
const uncertain = phase => ({state: 'uncertain', phase, provider_retry_allowed: false});
const known = new Set(['claimed', 'provider_reserved', 'generated', 'published', 'failed']);
function matches(record, request) {
  return record && record.schema_version === LIFECYCLE_VERSION
    && record.request_key === request.request_key && record.round_id === request.round_id
    && record.report_sha256 === request.report_sha256 && known.has(record.state);
}
// Adapter proposto: tutte le operazioni DB sono autenticate, bounded e atomiche.
// acquire non autorizza il provider; reserve concede un solo granted_now.
// persist è idempotente per chiave+hash; publish usa SOLO il risultato persistito.
export async function runSceneNarrative(request, d) {
  if (!request || Object.keys(request).length !== 3 || !['request_key', 'round_id', 'report_sha256'].every(k => typeof request[k] === 'string')
    || !/^[a-f0-9]{64}$/.test(request.report_sha256)) return {state: 'rejected', phase: 'ingress'};
  const observe = async () => {
    try { const r = await d.phase('status', signal => d.status(request, signal)); return matches(r, request) ? r : null; }
    catch (e) { if ((e?.message === 'scene_contract_incompatible' || e?.message === 'scene_count_contract_incompatible')) return {incompatible: true}; return null; }
  };
  let record;
  try { record = await d.phase('claim', signal => d.acquire(request, signal)); }
  catch (e) { if ((e?.message === 'scene_contract_incompatible' || e?.message === 'scene_count_contract_incompatible')) return {state: 'rejected', phase: 'contract'}; }
  if (!matches(record, request)) record = await observe();
  if (record?.incompatible) return {state: 'rejected', phase: 'contract'};
  if (!record) return uncertain('claim');
  if (record.state === 'published' || record.state === 'failed') return {state: record.state, completion: record.completion};
  if (record.state === 'provider_reserved') return uncertain('provider_authorization');
  async function publish() {
    try {
      const r = await d.phase('publish', signal => d.publish(request, signal));
      if (matches(r, request) && r.state === 'published') return {state: 'published', completion: r.completion};
    } catch { /* nessuna rigenerazione per una ricevuta persa */ }
    const r = await observe();
    return r?.state === 'published' ? {state: 'published', completion: r.completion, reconciled: true} : uncertain('publication');
  }
  if (record.state === 'generated') return publish();
  if (record.edge_revision !== EDGE_REVISION || record.validator_revision !== VALIDATOR_REVISION)
    return {state: 'rejected', phase: 'version'};
  let prompts;
  try {
    prompts = await scenePrompts(record.scene, record.binding, d.limits);
    if (record.binding.round_id !== request.round_id || record.binding.report_sha256 !== request.report_sha256)
      throw new Error('request_binding_changed');
    // Misura il payload EFFETTIVO dell'adattatore, incluse istruzioni e busta API.
    await d.checkProviderBudget(prompts);
  } catch { return {state: 'rejected', phase: 'context_or_budget'}; }
  let permission;
  try {
    permission = await d.phase('reserve', signal => d.reserve(request, {
      snapshot_sha256: record.scene.snapshot_sha256, control_version: record.binding.control_version,
    }, signal));
  } catch { return uncertain('provider_authorization'); }
  if (!matches(permission, request) || permission.state !== 'provider_reserved' || permission.granted_now !== true)
    return uncertain('provider_authorization');
  let attempts = 0;
  const onAttempt = () => { if (attempts !== 0) throw new Error('second_provider_forbidden'); attempts = 1; };
  let result;
  try {
    const ai = await d.phase('provider', signal => d.generate(prompts, signal, onAttempt, permission));
    const provenance = ai && ai.provider === 'openai' && ai.model === 'gpt-6-luna'
      && attempts === 1 && ai.http_attempts === 1 && typeof ai.response_id === 'string' && ai.response_id.length > 0
      && /^[a-f0-9]{64}$/.test(ai.request_sha256) && /^[a-f0-9]{64}$/.test(ai.raw_sha256)
      && Number.isSafeInteger(ai.input_tokens) && ai.input_tokens >= 0 && Number.isSafeInteger(ai.output_tokens) && ai.output_tokens > 0;
    const inspection = inspectNarrative(ai?.text, {providerComplete: ai?.complete === true, ...d.limits,
      mechanicalCodes: await d.mechanicalCodes(ai?.text, record.scene.snapshot)});
    result = {status: provenance && inspection.text ? 'succeeded' : 'failed', text: provenance ? inspection.text : null,
      failure_codes: [...inspection.codes, ...(!provenance ? ['provider_provenance_invalid'] : [])],
      advisories: inspection.advisories, http_attempts: attempts,
      provider: 'openai', model: 'gpt-6-luna', response_id: provenance ? ai.response_id : null,
      request_sha256: provenance ? ai.request_sha256 : null, raw_sha256: provenance ? ai.raw_sha256 : null,
      input_tokens: provenance ? ai.input_tokens : null, output_tokens: provenance ? ai.output_tokens : null};
  } catch { result = {status: 'failed', text: null, failure_codes: ['provider_or_validation_uncertain'], http_attempts: attempts}; }
  const succeeded = result.status === 'succeeded';
  const delivery = {schema_version: 'ordinary-narrative-result/2', status: result.status,
    report_sha256: request.report_sha256, context_sha256: record.scene.snapshot_sha256,
    control_version: record.binding.control_version, edge_revision: EDGE_REVISION, validator_revision: VALIDATOR_REVISION,
    text: succeeded ? result.text : null, text_sha256: succeeded ? await digest(result.text) : null,
    validation_passed: succeeded, provider: 'openai', model: 'gpt-6-luna',
    provider_response_id: result.response_id ?? null, provider_request_sha256: result.request_sha256 ?? null,
    raw_output_sha256: result.raw_sha256 ?? null, input_tokens: result.input_tokens ?? null, output_tokens: result.output_tokens ?? null,
    http_attempts: result.http_attempts, failure_code: succeeded ? null : 'provider_error'};
