 ||p.schema_version!=='combat-s22-budget/1'||p.session_id!==SESSION||session!==SESSION||p.deadline!=='2026-11-09T18:16:08Z'
 ||p.model!=='gpt-6-luna'||p.max_input_tokens!==16384||p.max_output_tokens!==8192||p.generation_upper_usd!==0.0057344||p.count_upper_usd!==0
 ||p.max_count_calls!==9||p.max_generation_calls!==9||p.input_usd_million!==0.1||p.output_usd_million!==0.5||p.policy_sha256!==POLICY)bad();
 return Object.freeze({...p});
}
// Keep exactly JSON.stringify(responsePayload). Count removes only store/max_output_tokens.
export async function measureResponsePayload(payload,limits){
 const payload_text=JSON.stringify(payload);
 if(payload.max_output_tokens!==limits.maxOutputTokens||new TextEncoder().encode(payload_text).length>limits.maxRequestBytes)
  throw new Error('scene_provider_request_overflow');
 const {store,max_output_tokens,...count_payload}=payload;
 return Object.freeze({payload_text,generation_request_sha256:await requestSha(payload_text),count_payload:Object.freeze(count_payload)});
}
export function validateS22Measurement(m){
 if(!object(m)||typeof m.payload_text!=='string'||typeof m.generation_request_sha256!=='string'||!/^[a-f0-9]{64}$/.test(m.generation_request_sha256))bad();
 let p;try{p=JSON.parse(m.payload_text);}catch{bad();}
 if(!exact(p,['model','instructions','input','max_output_tokens','store','reasoning'])||p.model!=='gpt-6-luna'||p.store!==false||p.max_output_tokens!==8192
 ||typeof p.instructions!=='string'||typeof p.input!=='string'||!exact(p.reasoning,['effort'])||p.reasoning.effort!=='high'
 ||!exact(m.count_payload,['model','instructions','input','reasoning'])||JSON.stringify(p)!==m.payload_text)bad();
