const startKeys=['schema_version','granted_now','may_count_http','count_ticket','generation_request_sha256','max_input_tokens','max_output_tokens','reused_proof','count_upper_usd'];
export function validateCountStart(s,sha){
 if(!exact(s,startKeys)||s.schema_version!=='combat-count-start/1'||!uuid(s.count_ticket)||s.generation_request_sha256!==sha
 ||s.max_input_tokens!==16384||s.max_output_tokens!==8192||s.count_upper_usd!==0||typeof s.granted_now!=='boolean'||typeof s.may_count_http!=='boolean')bad();
 if(s.granted_now===true){if(s.may_count_http!==true||s.reused_proof!==null)bad();return false;}
 if(s.may_count_http!==false)bad();
 validateCountFinish(s.reused_proof,s,sha,'success');
