}
export function validCountResponse(r){return exact(r,['object','input_tokens'])&&r.object==='response.input_tokens'&&Number.isSafeInteger(r.input_tokens)&&r.input_tokens>=0&&r.input_tokens<=2147483647;}
export function validateCountFinish(p,s,sha,status){
 if(!exact(p,['schema_version','generation_request_sha256','input_tokens','max_input_tokens','generation_allowed','count_ticket','count_charged_usd'])
 ||p.schema_version!=='combat-count-proof/1'||p.generation_request_sha256!==sha||p.count_ticket!==s.count_ticket||p.max_input_tokens!==16384||p.count_charged_usd!==0||typeof p.generation_allowed!=='boolean')bad();
 if(status==='success'){
  if(!Number.isSafeInteger(p.input_tokens)||p.input_tokens<0||p.generation_allowed!==(p.input_tokens<=16384))bad();
 }else if(p.input_tokens!==null||p.generation_allowed!==false)bad();
