import {runSceneNarrative} from './lifecycle.mjs';
import {canonical} from './scene.mjs';
import {EDGE_REVISION,VALIDATOR_REVISION} from './editorial.mjs';
import {SceneBudget} from './runtime.ts';
export async function sceneUser(body, channel, options) {
  if (!body || Object.keys(body).length!==1 || !/^[a-f0-9-]{36}$/i.test(body.user_test_reservation)) return {status:400,data:{error:'user_scene_request_invalid'}};
  const budget=new SceneBudget(50000-(Date.now()-options.startedAt));
  const bindingResponse=await budget.run('status', signal=>channel.rpc('test_room_user_ai_binding_v2',{p_reservation:body.user_test_reservation},signal));
  if(bindingResponse.error||!bindingResponse.data) return {status:503,data:{error:'user_scene_binding_unavailable'}};
  const b=bindingResponse.data;
  const request={round_id:b.round_id,report_sha256:b.report_sha256,request_key:b.request_key};
  const rpc=async(name,extra,signal)=>{const r=await channel.rpc(name,{p_reservation:body.user_test_reservation,...extra},signal);if(r.error||!r.data)throw new Error('scene_rpc_uncertain');return r.data;};
  const limits = {transportMaxChars: 5000, maxInputBytes: 49152, maxRequestBytes: 65536, maxOutputTokens: 9992};
  const checkedRecord = (r) => {
    if (!r.limits || Object.keys(r.limits).length !== Object.keys(limits).length
      || Object.entries(limits).some(([k,v]) => r.limits[k] !== v)
      || r.scene?.snapshot?.selection?.max_input_bytes !== limits.maxInputBytes)
      throw new Error('scene_contract_incompatible');
    return r;
  };
  let aiUsage;
  const result = await runSceneNarrative(request, {
    limits, phase: (p, fn) => budget.run(p, fn),
    acquire: async (_, signal) => {
      return checkedRecord(await rpc('test_room_user_scene_acquire_v2', {}, signal));
    },
    status: async (_, signal) => checkedRecord(await rpc('test_room_user_scene_status_v2', {}, signal)),
    reserve: (_, b, signal) => rpc('test_room_user_scene_permit_v2', {p_scene_sha256: b.snapshot_sha256, p_control_version: b.control_version}, signal),
    persist: (_, p, _hash, signal) => rpc('test_room_user_scene_save_v2', {p_result_text: canonical(p)}, signal),
    publish: (_, signal) => rpc('test_room_user_scene_complete_v2', {}, signal),
    checkProviderBudget: async (p) => options.measure(p, limits),
    generate: async (p, signal, onAttempt) => {
      const ai = await options.generate(p, signal, onAttempt, limits); aiUsage = ai;
      return {provider: ai.provider, model: ai.model, http_attempts: ai.tentativi_http, response_id: ai.provider_response_id,
        request_sha256: ai.provider_request_sha256, raw_sha256: ai.raw_output_sha256,
        input_tokens: ai.input_tokens, output_tokens: ai.output_tokens, text: ai.text,
        complete: ai.ok === true && ai.stop_reason === 'end_turn' && ai.troncato !== true};
    },
    mechanicalCodes: (raw, snapshot) => options.mechanicalCodes(raw, JSON.parse(snapshot.resolved_facts)),
    audit: (delivery, diagnostics, signal) => options.audit(aiUsage, delivery, diagnostics, signal),
  });
  return {status: result.state === 'published' || result.state === 'failed' ? 200 : 503,
    data: {...result, edge_revision: EDGE_REVISION, validator_revision: VALIDATOR_REVISION}};
}

// ============================================================================
// adattatore.ts · AI-NARRATOR-HAIKU-LUNA-046 · SORGENTE CANONICO
// ----------------------------------------------------------------------------
// L'unica porta verso un modello per le Edge narrative del progetto.
//
// Perché esiste. Oggi `combat_narratore_ai` e `exam_genin_ai` chiamano
// modello arriva — nel combattimento — da una riga di database
// (`ai_agents.model`, letta da `combat_narratore_context`). Finché esiste un
// solo provider quella riga è innocua. Con due provider diventa un instradatore
// travestito da configurazione: basta scriverci uno slug OpenAI perché una
// punto dove nessuno sta guardando.
//
// La regola di questo file, in una riga:
//   ⛔ IL PROVIDER NON SI DEDUCE MAI DA UN DATO SCRIVIBILE.
//      Si legge da un registro chiuso, scritto qui, e uno slug che non è nel
//      registro NON PRODUCE NESSUNA CHIAMATA.
//
// La seconda regola:
//   ⛔ NESSUN RIPIEGO IMPLICITO FRA PROVIDER.
//      Un errore OpenAI è un errore, e finisce nel ripiego deterministico che
//      funzione `chiama` esegue AL PIÙ UNA `fetch`, sempre, per costruzione:
//      il contatore `tentativiHttp` lo dimostra al banco.
//
// La terza regola:
//   ⛔ NESSUN SEGRETO ESCE DA QUI.
//      La chiave si legge dall'ambiente Supabase al momento della chiamata, si
//      usa in un header e non entra in nessun ritorno, nessun `detail`, nessun
//      diario, nessuna telemetria. `detail` è troncato e passa da `spolpa()`.
//
// ⚠️ QUESTO FILE È UNO SOLO. Le copie depositate dentro i due candidati devono
//    avere lo STESSO sha256 di questo. Lo verifica `strumenti/verifica.py` e lo
//    riverifica il banco: due copie che divergono in silenzio sono esattamente
//    il difetto che la 084-A12 ha pagato fra guardia SQL e specchio TypeScript.
// ============================================================================

// ---------------------------------------------------------------------------
// 1 · L'uscita comune
// ---------------------------------------------------------------------------
// I primi sette campi sono, alla lettera, il tipo `EsitoChiamata` che
// `exam_genin_ai/validatore.ts` già dichiara (riga 827 del file vivo v11) e che
// il piano 046-A0 fissa come uscita comune. Tutto il resto è ADDITIVO: un
// consumer che non lo legge continua a funzionare identico.
export type UscitaModello = {
  ok: boolean;
  provider_response_id?: string | null;
  provider_request_sha256?: string;
  raw_output_sha256?: string;
  text?: string;
  stop_reason?: string | null;
  input_tokens?: number | null;
  output_tokens?: number | null;
  status?: number;
  detail?: string;

  // ---- additivi: telemetria confrontabile (046-A0 §3) ---------------------
  provider?: Provider;
  model?: string;
  braccio?: Braccio;
  reasoning_effort?: string | null;
  reasoning_tokens?: number | null;
  latency_ms?: number;
  tentativi_http?: number;
  troncato?: boolean;
};

export type Provider = "openai";

// ---------------------------------------------------------------------------
// 2 · Il registro chiuso modello → provider
// ---------------------------------------------------------------------------
// SEDE UNICA. Uno slug che non compare qui non ha provider, e senza provider
// non c'è chiamata. Non esiste un ramo «default».
export const REGISTRO_MODELLI: Readonly<Record<string, Provider>> = Object.freeze({
  "gpt-6-luna": "openai",
});

export function providerDi(modello: string | null | undefined): Provider | null {
  const m = String(modello ?? "").trim();
  if (!m) return null;
  return REGISTRO_MODELLI[m] ?? null;
}

// ---------------------------------------------------------------------------
// 3 · I bracci del confronto
// ---------------------------------------------------------------------------
// I bracci sono DUE, e uno solo è di Luna.
//
// 🔴 DECISIONE DI ANTONELLO del 21/08/2026: l'unico braccio Luna è
//    `reasoning.effort: "high"`. I due bracci `none` e `low` previsti dal piano
//    046-A0 §2 sono RITIRATI: non stanno in questo file, non stanno nei banchi e
//    non stanno nell'harness. Un braccio ritirato che sopravvive in un elenco è
//    un braccio che qualcuno rieseguirà.
//
// ⚠️ `modello: null` nel braccio di baseline NON è una dimenticanza: la
//    baseline conserva il comportamento vivo, cioè il modello che il consumer
//    l'Esame la costante `MODELLO` del contratto). Il braccio non lo riscrive.
export type Braccio = "openai_luna_high";

export type DefinizioneBraccio = {
  provider: Provider;
