export const BRACCI: Readonly<Record<Braccio, DefinizioneBraccio>> = Object.freeze({
  openai_luna_high: Object.freeze({
    provider: "openai",
    modello: "gpt-6-luna",
    // 🔴 L'unico braccio Luna, per decisione di Antonello del 21/08/2026.
    reasoning: "high",
    // ⚠️ FALSO PER SCELTA, non per svista. La documentazione OpenAI dichiara
    //    `temperature` non inviata a `gpt-6-luna`, ma «supportato» non vuol
    //    dire «equivalente»: il piano 046-A0 §2 vieta di trascrivere la
    //    verificata. Finché il corpus non dice il contrario il parametro NON
    //    viene spedito, e resta OPEN-046-2.
    trasmetti_temperatura: false,
    // 🔴🔴 ZERO, e con `effort: "high"` questa riga è la più pericolosa del file.
    //
    //    Su Responses `max_output_tokens` limita TESTO PIÙ RAGIONAMENTO, e il
    //    ragionamento si spende per primo. Con `high` il modello ragiona molto:
    //    su un tetto largo non si nota, su un tetto stretto la prosa non nasce
    //    proprio. Il combattimento ha un tetto di 900 token e rifiuta i testi
    //    sotto i 500 caratteri: i due numeri insieme dicono che il margine è
    //    quasi nullo.
    //
    //    Zero resta il valore consegnato perché è l'unico fedele alla
    //    prescrizione «stessi tetti della baseline» del piano §2, e perché
    //    alzare un tetto è una decisione del PM, non dell'implementazione.
    //    L'harness misura che cosa succede a zero e che cosa succederebbe con
    //    una riserva (`--riserva N`), così la decisione si prende su due
    //    colonne di numeri invece che su un'impressione. OPEN-046-3.
    riserva_ragionamento: 8192,
  }),
});

// ---------------------------------------------------------------------------
// 4 · La chiave, e dove NON va
// ---------------------------------------------------------------------------
// Le chiavi stanno SOLO nell'ambiente Supabase. Questo file non ne scrive
// nessuna, non ne stampa nessuna e non ne mette nessuna nel ritorno.
export function nomeChiave(): "OPENAI_API_KEY" {
  return "OPENAI_API_KEY";
}

type LettoreAmbiente = (nome: string) => string | undefined;

const AMBIENTE_PREDEFINITO: LettoreAmbiente = (nome) => {
  // `Deno` non esiste quando questo file gira dentro il banco in Node: in quel
  // caso non c'è ambiente, non c'è chiave e non parte nessuna chiamata vera.
  // deno-lint-ignore no-explicit-any
  const d = (globalThis as any).Deno;
  return d?.env?.get ? d.env.get(nome) : undefined;
};

// ---------------------------------------------------------------------------
// 5 · La richiesta
// ---------------------------------------------------------------------------
export type RichiestaModello = {
  braccio: Braccio;
  /** Il modello che il consumer dichiara. Usato SOLO dal braccio di baseline. */
  modelloConsumer?: string | null;
  sistema: string;
  utente: string;
  /** Il tetto d'uscita del consumer, invariato. */
  maxTokens: number;
  /** La temperatura del consumer, se ne ha una. */
  temperatura?: number | null;
  signal?: AbortSignal;
  /** Iniettabile dal banco. In esercizio resta `undefined`. */
  fetchImpl?: typeof fetch;
  /** Iniettabile dal banco. In esercizio resta `undefined`. */
  ambiente?: LettoreAmbiente;
  /** Iniettabile dal banco per rendere la latenza misurabile e ripetibile. */
  orologio?: () => number;
};

const CAP_DETTAGLIO = 600;

/** Toglie da un testo destinato al referto qualunque cosa somigli a una chiave.
 *  Non è una promessa di sicurezza: è una rete in più su un campo che finisce
 *  in `p_ctx`, cioè a database. */
export function spolpa(s: unknown): string {
  // ⚠️ L'ORDINE CONTA. Prima si toglie l'intestazione INTERA fino a fine riga —
  //    altrimenti la regola sullo slug la spezza a metà e resta il contorno —
  //    e solo dopo si mascherano gli slug rimasti dentro il testo.
  return String(s ?? "")
    .replace(/(?:authorization|api[-_]?key)\s*[:=]\s*[^\n\r]+/gi, "«omessa»")
    .replace(/sk-[A-Za-z0-9_\-]{8,}/g, "sk-«omessa»")
    .slice(0, CAP_DETTAGLIO);
}

// ---------------------------------------------------------------------------
// 6 · La normalizzazione di `stop_reason` — il punto in cui si rompe tutto
// ---------------------------------------------------------------------------
// `'max_tokens'` NON è una parola descrittiva: è un VALORE DI CONTRATTO. Lo
// confronta `validatore.ts` (`if (LEVE.tetto_token && stopReason === "max_tokens")`)
// e lo confronta la funzione `public.esame_narrazione_apply` dentro la
// transazione. Le Responses API non dicono `max_tokens`: dicono
// `status: "incomplete"` con `incomplete_details.reason = "max_output_tokens"`.
//
// Se l'adattatore lasciasse passare la parola di OpenAI, il tetto raggiunto
// smetterebbe di essere rilevato da entrambe le guardie e una risposta troncata
// verrebbe pubblicata come se fosse intera. È il difetto peggiore possibile in
// questa migrazione, e sta tutto in questa funzione.
export function normalizzaStopOpenAI(d: {
  status?: string | null;
  incomplete_details?: { reason?: string | null } | null;
}): string | null {
  const st = String(d?.status ?? "").trim();
  if (st === "completed") return "end_turn";
  if (st === "incomplete") {
    const r = String(d?.incomplete_details?.reason ?? "").trim();
    if (r === "max_output_tokens") return "max_tokens";
    return r ? `incomplete:${r}` : "incomplete";
  }
  if (!st) return null;
  return st;
}

/** Estrae il testo da una risposta Responses. `output_text` è la comodità
 *  documentata; la passeggiata su `output[]` è la strada che regge anche
 *  quando in mezzo agli item c'è un blocco `reasoning`. */
export function testoDaResponses(d: unknown): string {
  const o = d as Record<string, unknown>;
  if (typeof o?.output_text === "string") return o.output_text.trim();
  const out = Array.isArray(o?.output) ? (o.output as unknown[]) : [];
  const pezzi: string[] = [];
  for (const item of out) {
    const it = item as Record<string, unknown>;
    if (it?.type !== "message") continue;
    const parti = Array.isArray(it?.content) ? (it.content as unknown[]) : [];
    for (const p of parti) {
      const pp = p as Record<string, unknown>;
      if (pp?.type === "output_text" && typeof pp?.text === "string") pezzi.push(pp.text);
    }
  }
  return pezzi.join("").trim();
}

// ---------------------------------------------------------------------------
// 7 · La chiamata
// ---------------------------------------------------------------------------
export function responsePayload(r: RichiestaModello): Record<string, unknown> {
  if (!Object.hasOwn(BRACCI,r.braccio)) throw new Error('scene_provider_configuration_invalid');
  const def=BRACCI[r.braccio];
  const modello=def.modello ?? String(r.modelloConsumer ?? '').trim();
    const corpo: Record<string, unknown> = {
      model: modello,
      instructions: r.sistema,
      input: r.utente,
      max_output_tokens: r.maxTokens + def.riserva_ragionamento,
      // `store: false` — il testo di gioco non resta sui server del provider.
      // Non è una richiesta del piano: è la scelta prudente, ed è dichiarata.
      store: false,
    };
    if (def.reasoning) corpo.reasoning = { effort: def.reasoning };
    if (def.trasmetti_temperatura && typeof r.temperatura === "number") {
      corpo.temperature = r.temperatura;
    }
  return corpo;
}

export async function chiama(r: RichiestaModello): Promise<UscitaModello> {
  // 🔴 `Object.hasOwn`, non `r.braccio in BRACCI`. L'operatore `in` cammina sul
  //    prototipo: `"__proto__" in BRACCI` è VERO, e `BRACCI["__proto__"]`
  //    restituisce `Object.prototype`, che è un oggetto verissimo con
  //    `provider` e `modello` a `undefined`. Un insieme «chiuso» interrogato
  //    con `in` non è chiuso. Trovato dal banco del giunto, prova P10.
  const def = Object.hasOwn(BRACCI, r.braccio) ? BRACCI[r.braccio] : undefined;
  const ora = r.orologio ?? (() => Date.now());
  const partito = ora();

  // -- il braccio deve esistere. Non c'è un ramo «altrimenti fai la baseline».
  if (!def) {
    return {
      ok: false, status: 0, detail: `braccio sconosciuto: ${spolpa(r.braccio)}`,
      provider: undefined, braccio: r.braccio, tentativi_http: 0, latency_ms: 0,
    };
  }

  // -- il modello effettivo -------------------------------------------------
  const modello = def.modello ?? String(r.modelloConsumer ?? "").trim();
  const provRegistro = providerDi(modello);

  // 🔴 LA GUARDIA CHE GIUSTIFICA QUESTO FILE.
  //    Uno slug che non è nel registro non viene spedito da nessuna parte.
  if (provRegistro === null) {
    return {
      ok: false, status: 0,
      detail: `modello fuori registro: ${spolpa(modello) || "«vuoto»"}`,
      model: modello || undefined, braccio: r.braccio,
      reasoning_effort: def.reasoning, tentativi_http: 0, latency_ms: 0,
    };
  }
  //    E uno slug del provider sbagliato non viene spedito all'endpoint
  //    dell'altro. È il caso `ai_agents.model = 'gpt-6-luna'` con il braccio
  if (provRegistro !== def.provider) {
    return {
      ok: false, status: 0,
      detail: `instradamento rifiutato: il modello «${spolpa(modello)}» è di ${provRegistro}, il braccio ${r.braccio} è di ${def.provider}`,
      model: modello, provider: def.provider, braccio: r.braccio,
      reasoning_effort: def.reasoning, tentativi_http: 0, latency_ms: 0,
    };
  }

  const provider = def.provider;
  const leggi = r.ambiente ?? AMBIENTE_PREDEFINITO;
  const chiave = leggi(nomeChiave());
  if (!chiave) {
    return {
      ok: false, status: 0,
      detail: `chiave assente per ${provider} (${nomeChiave()})`,
      model: modello, provider, braccio: r.braccio,
      reasoning_effort: def.reasoning, tentativi_http: 0, latency_ms: 0,
    };
  }

  const comune = {
    provider, model: modello, braccio: r.braccio,
    reasoning_effort: def.reasoning,
  };

  // -- UNA sola `fetch`, e il contatore lo dimostra -------------------------
  let tentativi = 0;
  const eseguiFetch = r.fetchImpl ?? fetch;

  try {
    // ── Responses API · il percorso nuovo ─────────────────────────────────
    // `instructions` è la sede del sistema; `input` quella del turno utente.
    // La forma a stringa è quella documentata e basta a riprodurre l'unico
    // messaggio `user` che entrambi i consumer già mandano: nessun consumer
    // manda una conversazione a più turni.
    const corpo = responsePayload(r);
    tentativi += 1;
    const risp = await eseguiFetch("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "authorization": `Bearer ${chiave}`,
      },
      body: JSON.stringify(corpo),
      signal: r.signal,
    });
    if (!risp.ok) {
      const t = await risp.text();
      //    ripiego deterministico: è quello, e si vede nel referto.
      return { ok: false, status: risp.status, detail: spolpa(t), ...comune,
               tentativi_http: tentativi, latency_ms: ora() - partito };
    }
    const d = await risp.json();
    if (String(d?.status ?? "") === "failed") {
      return {
        ok: false, status: 200,
        detail: spolpa(d?.error?.message ?? "risposta failed"),
        ...comune, tentativi_http: tentativi, latency_ms: ora() - partito,
      };
    }
    const stop = normalizzaStopOpenAI(d);
    // Provenienza additiva per il raccordo ordinary: solo corpo richiesta/risposta,
    // mai header, chiavi o segreti. Nessun identificativo inventato.
    const digest = async (value: string) => Array.from(new Uint8Array(
      await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)),
    )).map((n) => n.toString(16).padStart(2, "0")).join("");
    return {
      ok: true,
      provider_response_id: typeof d?.id === "string" ? d.id : null,
      provider_request_sha256: await digest(JSON.stringify(corpo)),
      raw_output_sha256: await digest(JSON.stringify(d)),
      text: testoDaResponses(d),
      stop_reason: stop,
      input_tokens: typeof d?.usage?.input_tokens === "number" ? d.usage.input_tokens : null,
      output_tokens: typeof d?.usage?.output_tokens === "number" ? d.usage.output_tokens : null,
      reasoning_tokens:
        typeof d?.usage?.output_tokens_details?.reasoning_tokens === "number"
          ? d.usage.output_tokens_details.reasoning_tokens
          : null,
      troncato: stop === "max_tokens",
      ...comune, tentativi_http: tentativi, latency_ms: ora() - partito,
    };
  } catch (e) {
    // Rete caduta, timeout, abort: dal punto di vista del consumer il modello
    // ha taciuto. È lo stesso caso che i due consumer già conoscono.
    return {
      ok: false, status: 0, detail: spolpa((e as Error)?.message ?? e),
      ...comune, tentativi_http: tentativi, latency_ms: ora() - partito,
    };
  }
}

// ---------------------------------------------------------------------------
// 8 · La telemetria, in una forma sola
// ---------------------------------------------------------------------------
// Quello che ogni referto di prova deve portare (046-A0 §3). Non contiene testo
// di gioco e non contiene segreti: è fatto per finire dentro un `jsonb`.
export function telemetria(u: UscitaModello, extra?: Record<string, unknown>) {
  return {
    provider: u.provider ?? null,
    modello: u.model ?? null,
    braccio: u.braccio ?? null,
    reasoning_effort: u.reasoning_effort ?? null,
    input_tokens: u.input_tokens ?? null,
    output_tokens: u.output_tokens ?? null,
    reasoning_tokens: u.reasoning_tokens ?? null,
    stop_reason: u.stop_reason ?? null,
    troncato: u.troncato ?? null,
    latenza_ms: u.latency_ms ?? null,
    tentativi_http: u.tentativi_http ?? null,
    esito_http: u.status ?? null,
    ...(extra ?? {}),
  };
}

// 🔴 La versione sale insieme all'insieme dei bracci, e non è cosmesi: un
//    referto vecchio dice `046-A1` e parla di un mondo in cui esistevano
//    `openai_luna_none` e `openai_luna_low`. Chi confronta due corse deve
//    vedere subito che non sono confrontabili.
export const ADATTATORE_VERSIONE = "046-A3 · solo OpenAI Responses Luna high";

// Candidato OFFLINE: nessun ripiego legacy, una sola chiamata per claim.
import type { UscitaModello } from "./adattatore.ts";
import { OrdinaryBudget, OrdinaryTimeout } from "./transport.ts";
import { factsContext, FACTS_EDGE, factsValidatorRevision } from './facts.ts';
import { rinunciaContext, RINUNCIA_EDGE, RINUNCIA_VALIDATOR } from "./rinuncia.ts";
import { diagnosticRecord, type TextInspection } from "./diagnostics.ts";

type Rpc = (name: string, args: Record<string, unknown>, signal: AbortSignal) => PromiseLike<{ data: any; error: unknown }>;
type Dependencies = {
  rpc: Rpc;
  prompts: (context: any) => { sys: string; usr: string };
  call: (sys: string, usr: string, signal: AbortSignal, onAttempt: () => void) => Promise<UscitaModello>;
  validate: (text: string, context: any) => TextInspection;
  audit: (ai: UscitaModello, reportId: string, signal: AbortSignal, diagnostics: Awaited<ReturnType<typeof diagnosticRecord>>) => Promise<void>;
  budget?: OrdinaryBudget;
};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const sha = /^[a-f0-9]{64}$/;
const tokenCount = (n: unknown): n is number => Number.isSafeInteger(n) && (n as number) >= 0;
const digest = async (s: string) => Array.from(new Uint8Array(
  await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s)),
)).map((n) => n.toString(16).padStart(2, "0")).join("");

export async function ordinary(body: any, d: Dependencies): Promise<{ status: number; data: Record<string, unknown> }> {
  const budget = d.budget ?? new OrdinaryBudget();
  const keys = ["ordinary_round_id", "report_sha256", "request_key"];
  if (!body || Object.keys(body).length !== keys.length || keys.some((k) => typeof body[k] !== "string")
    || !uuid.test(body.ordinary_round_id) || !uuid.test(body.request_key) || !sha.test(body.report_sha256)) {
    return { status: 400, data: { error: "ordinary_request_invalid" } };
  }
  async function status(claimId: string | null) {
    try {
      const r = await budget.run("status", signal => d.rpc("combat_consumer_narrative_status_v1", {
        p_round: body.ordinary_round_id, p_report_sha256: body.report_sha256,
        p_request_key: body.request_key, p_claim: claimId,
      }, signal));
      return r.error ? null : r.data;
    } catch { return null; }
  }
  let claimed;
  try {
    claimed = await budget.run("claim", signal => d.rpc("combat_consumer_narrative_claim_v1", {
      p_round: body.ordinary_round_id, p_report_sha256: body.report_sha256, p_request_key: body.request_key,
    }, signal), { reserveMs: 8000 });
  } catch { claimed = { data: null, error: "uncertain" }; }
  if (claimed.error || !claimed.data) {
    const observed = await status(null);
    return { status: 503, data: { error: "ordinary_claim_unavailable", state: observed?.state ?? "unknown" } };
  }
  const c = claimed.data;
  if (c.should_call_provider !== true) {
    return { status: 200, data: { skipped: true, state: c.state, completion: c.completion ?? null } };
  }
  // Il contesto viene soltanto dal claim autenticato. Una shape sconosciuta non autorizza HTTP.
  if (!uuid.test(c.claim_id) || !uuid.test(c.report_id) || c.round_id !== body.ordinary_round_id
    || c.report_sha256 !== body.report_sha256 || !sha.test(c.context_sha256)
    || !Number.isSafeInteger(c.control_version) || c.control_version < 1) {
    return { status: 503, data: { error: "ordinary_claim_contract_invalid" } };
  }
  const result: Record<string, any> = {
    schema_version: "ordinary-narrative-result/1", status: "failed",
    report_sha256: c.report_sha256, context_sha256: c.context_sha256, control_version: c.control_version,
    edge_revision: c.context?.genere === "rinuncia" ? RINUNCIA_EDGE : c.context?.genere === "azione_risolta" ? FACTS_EDGE : "ordinary-adapter/1",
    validator_revision: c.context?.genere === "rinuncia" ? RINUNCIA_VALIDATOR : c.context?.genere === "azione_risolta" ? factsValidatorRevision(c.context) : "combat-narratore-v18-existing/1",
    provider_response_id: null, provider_request_sha256: null, raw_output_sha256: null,
    text: null, text_sha256: null, validation_passed: false, provider: "openai", model: "gpt-6-luna",
    input_tokens: null, output_tokens: null, http_attempts: 0, failure_code: "configuration_mismatch",
  };
  const remaining = Date.parse(c.expires_at) - Date.now() - 8000;
  const allowed = c.edge_revision === result.edge_revision && c.validator_revision === result.validator_revision
    && c.provider === result.provider && c.model === result.model
    && c.context?.ordinary === true && (c.context?.genere === "confronto" || rinunciaContext(c.context) || factsContext(c.context))
    && c.context?.model === result.model && Number.isFinite(remaining) && remaining > 0;
  if (allowed) {
    try {
      const { sys, usr } = d.prompts(c.context);
      // Nessun ciclo o retry del provider: l'adattatore restituisce il contatore HTTP effettivo.
      const ai = await budget.run("model", signal => d.call(sys, usr, signal, () => {
        if (result.http_attempts !== 0) throw new Error("ordinary_second_attempt_forbidden");
        result.http_attempts = 1;
      }), { reserveMs: 8000, leaseRemainingMs: Date.parse(c.expires_at) - Date.now() });
      result.http_attempts = Math.max(result.http_attempts, ai.tentativi_http === 1 ? 1 : 0);
      result.input_tokens = tokenCount(ai.input_tokens) ? ai.input_tokens : null;
      result.output_tokens = tokenCount(ai.output_tokens) ? ai.output_tokens : null;
      result.provider_response_id = typeof ai.provider_response_id === "string"
        && ai.provider_response_id.length > 0 && ai.provider_response_id.length <= 200 ? ai.provider_response_id : null;
      result.provider_request_sha256 = sha.test(ai.provider_request_sha256 ?? "") ? ai.provider_request_sha256 : null;
      result.raw_output_sha256 = sha.test(ai.raw_output_sha256 ?? "") ? ai.raw_output_sha256 : null;
      result.failure_code = "provider_error";
      let inspection: TextInspection | null = null;
      let validationError: unknown;
      let validationThrew = false;
      if (ai.ok) {
        try { inspection = d.validate(ai.text ?? "", c.context); }
        catch (error) { validationThrew = true; validationError = error; }
      }
      const provenance = {
        response_id: Boolean(result.provider_response_id),
        request_sha: Boolean(result.provider_request_sha256),
        raw_sha: Boolean(result.raw_output_sha256),
        input_tokens: result.input_tokens !== null,
        output_tokens: result.output_tokens > 0,
        http_attempts: ai.tentativi_http === 1,
        provider: ai.provider === result.provider,
        model: ai.model === result.model,
      };
      const diagnostics = await diagnosticRecord(inspection, provenance,
        validationThrew ? "validator_exception" : ai.ok ? "evaluated" : "provider_not_ok", result.validator_revision);
      await budget.run("audit", signal => d.audit(ai, c.report_id, signal, diagnostics), { reserveMs: 5000 });
      if (validationThrew) throw validationError;
      if (ai.ok) {
        const text = inspection?.text ?? null;
        result.failure_code = "validation_rejected";
        if (text && result.provider_response_id && result.provider_request_sha256 && result.raw_output_sha256
          && result.input_tokens !== null && result.output_tokens > 0 && ai.tentativi_http === 1
          && ai.provider === result.provider && ai.model === result.model) {
          const textHash = await digest(text);
          result.status = "succeeded";
          result.text = text;
          result.text_sha256 = textHash;
          result.validation_passed = true;
          result.failure_code = null;
        }
      }
    } catch (error) {
      // Nessun testo/error detail/role restituito o pubblicato come ripiego.
      result.failure_code = error instanceof OrdinaryTimeout ? "timeout" : "configuration_mismatch";
    }
  } else if (Number.isFinite(remaining) && remaining <= 0) result.failure_code = "timeout";
  let completed;
  try {
    completed = await budget.run("complete", signal => d.rpc("combat_consumer_narrative_complete_v1", {
      p_claim: c.claim_id, p_result: result, p_request_key: body.request_key,
    }, signal), { reserveMs: 2000 });
  } catch { completed = { data: null, error: "uncertain" }; }
  // Esito incerto: non si riavvia il modello. Il DB mantiene il claim e rifiuta una seconda consegna.
  if (completed.error || !completed.data) {
    const observed = await status(c.claim_id);
    if (["completed", "failed"].includes(observed?.state) && observed?.completion) {
      return { status: 200, data: { claim_id: c.claim_id, completion: observed.completion, reconciled: true } };
    }
    return { status: 503, data: { error: "ordinary_completion_uncertain", claim_id: c.claim_id, state: observed?.state ?? "unknown" } };
  }
  return { status: 200, data: { claim_id: c.claim_id, completion: completed.data } };
}

// Solo ordinary. Abort interrompe l'attesa/HTTP locale, non prova rollback remoto.
export class OrdinaryTimeout extends Error {
  constructor(readonly phase: string) { super("ordinary_transport_timeout"); }
}
export type OrdinaryPhase = "auth" | "claim" | "model" | "audit" | "complete" | "status";
const caps: Record<OrdinaryPhase, number> = {
  auth: 3000, claim: 3000, model: 45000, audit: 3000,
  complete: 3000, status: 2000, // 5s riserva consegna = 3s invio + 2s riconciliazione.
};
export class OrdinaryBudget {
  private readonly deadline: number;
  constructor(private readonly now: () => number = () => performance.now(), durationMs = 50000) {
    this.deadline = now() + durationMs;
  }
  remaining(): number { return Math.max(0, this.deadline - this.now()); }
  async run<T>(phase: OrdinaryPhase, fn: (signal: AbortSignal) => PromiseLike<T>,
    options: { reserveMs?: number; leaseRemainingMs?: number; capMs?: number } = {}): Promise<T> {
    const reserve = options.reserveMs ?? 0;
    const ms = Math.min(caps[phase], options.capMs ?? Infinity,
      this.remaining() - reserve, (options.leaseRemainingMs ?? Infinity) - reserve);
    if (!Number.isFinite(ms) || ms <= 0) throw new OrdinaryTimeout(phase);
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const timeout = new Promise<never>((_, reject) => {
      timer = setTimeout(() => {
        controller.abort();
        reject(new OrdinaryTimeout(phase));
      }, ms);
    });
    try {
      // Il segnale deve essere passato a fetch/abortSignal del builder dal chiamante.
      // race dà un bound anche se il peer risponde dopo l'abort: nessun retry qui.
      return await Promise.race([Promise.resolve().then(() => fn(controller.signal)), timeout]);
    } finally {
      if (timer !== undefined) clearTimeout(timer);
    }
  }
}

// Lettura abortibile: il marker sceglie il ramo, non autorizza la richiesta.
export async function ordinaryBody(req: Request, signal: AbortSignal): Promise<unknown> {
  if (!req.body) return null;
  const reader = req.body.getReader();
  const abort = () => { void reader.cancel().catch(() => {}); };
  signal.addEventListener("abort", abort, { once: true });
  const decoder = new TextDecoder();
  let text = "";
  try {
    while (true) {
      if (signal.aborted) throw new OrdinaryTimeout("auth");
      const chunk = await reader.read();
      if (signal.aborted) throw new OrdinaryTimeout("auth");
      if (chunk.done) break;
      text += decoder.decode(chunk.value, { stream: true });
    }
    text += decoder.decode();
    return JSON.parse(text);
  } finally { signal.removeEventListener("abort", abort); reader.releaseLock(); }
}

export function ordinaryRest(url: string, key: string, fetcher: typeof fetch = fetch) {
  const request = async (path: string, method: string, payload: unknown, signal: AbortSignal) => {
    // Una fetch reale per operazione; nessun wrapper SDK o retry implicito.
    const response = await fetcher(url.replace(/\/$/, "") + "/rest/v1/" + path, {
      method, signal, headers: { apikey: key, Authorization: "Bearer " + key,
        "Content-Type": "application/json", Prefer: path.startsWith("rpc/") ? "return=representation" : "return=minimal" },
      body: payload === undefined ? undefined : JSON.stringify(payload),
    });
    if (!response.ok) return { data: null, error: "ordinary_http_" + response.status };
    const text = await response.text();
    return { data: text ? JSON.parse(text) : null, error: null };
  };
  return {
    async tickToken(signal: AbortSignal) {
      const r = await request("academy_ai_runtime?select=tick_token&id=eq.1", "GET", undefined, signal);
      return r.error || !Array.isArray(r.data) || r.data.length !== 1 ? null : r.data[0].tick_token;
    },
    rpc(name: string, args: Record<string, unknown>, signal: AbortSignal) {
      if (!["combat_consumer_narrative_claim_v1", "combat_consumer_narrative_complete_v1",
        "combat_consumer_narrative_status_v1", "combat_consumer_scene_acquire_v2", "combat_consumer_scene_permit_v3",
        "combat_consumer_scene_status_v2", "combat_consumer_scene_save_v2", "combat_consumer_scene_complete_v2",
        "combat_consumer_scene_quota_send_v1", "combat_consumer_recovery_acquire_v1",
        "combat_consumer_recovery_permit_v2", "combat_consumer_recovery_status_v1",
        "combat_consumer_recovery_save_v1", "combat_consumer_recovery_complete_v1",
        "combat_consumer_recovery_quota_send_v1", "combat_consumer_count_start_v1", "combat_consumer_count_finish_v1"].includes(name)) throw new Error("ordinary_rpc_not_allowed");
      return request("rpc/" + name, "POST", args, signal);
    },
    async audit(row: unknown, signal: AbortSignal) {
      const r = await request("ai_orchestra_audit", "POST", row, signal);
      if (r.error) throw new Error("ordinary_audit_uncertain");
    },
  };
}

