         IF meta->>'source'='mano' THEN endpoint_cache:=jsonb_set(endpoint_cache,ARRAY[target_id::text],endpoint_options,true); END IF; /* INUZUKA-HOTFIX016-ZANNA-CONTACT-END */END IF;
       END IF;
